// ── MiniMap node (custom, with text label) ───────────────────────────────────
//
// Default MiniMap nodes are flat colored rectangles — at the chart's scale
// users can't tell which block is which. This component overlays an SVG
// <text> with the agent name (Rex / Arya / Vega …) or department name
// (Engineering / Design …) so the minimap is actually navigable.
//
// React Flow does not pass node.data into MiniMapNodeProps, so the label
// lookup is side-channelled through MinimapLabelContext (populated alongside
// the layout in TreeViewInner).

interface MinimapNodeProps {
  id: string
  x: number
  y: number
  width: number
  height: number
  borderRadius: number
  color: string
  shapeRendering: string
  strokeColor: string
  strokeWidth: number
  selected?: boolean
  className?: string
}

function MinimapNode(props: MinimapNodeProps) {
  const labelMap = useContext(MinimapLabelContext)
  const entry = labelMap.get(props.id)

  // Font size is in chart coords (the SVG viewBox uses chart-space units),
  // so it auto-scales when the user zooms the minimap. Leaders are short
  // single words, depts are 1–2 short words — pick by kind.
  const fontSize = entry?.kind === 'leader' ? 56 : 96

  // Center in leader cards, top-anchor in tall dept columns.
  const textX = props.x + props.width / 2
  const textY = entry?.kind === 'leader'
    ? props.y + props.height / 2 + fontSize / 3
    : props.y + 80 + fontSize / 3

  return (
    <g>
      <rect
        x={props.x}
        y={props.y}
        width={props.width}
        height={props.height}
        rx={props.borderRadius}
        ry={props.borderRadius}
        fill={props.color}
        stroke={props.strokeColor}
        strokeWidth={props.strokeWidth}
        shapeRendering={props.shapeRendering}
      />
      {entry && (
        <text
          x={textX}
          y={textY}
          fontSize={fontSize}
          fontWeight={700}
          fill="#ffffff"
          textAnchor="middle"
          pointerEvents="none"
          style={{ userSelect: 'none' }}
        >
          {entry.label}
        </text>
      )}
    </g>
  )
}

