// MiniMap label map — derived from the same layout. Keyed by node.id so the
// custom MinimapNode SVG component can look up "Rex" / "Arya" / "Engineering"
// / etc. by id (MiniMapNodeProps doesn't pass node.data through).
const minimapLabels = useMemo(() => {
  const m = new Map<string, MinimapLabelEntry>()
  for (const n of initialNodes) {
    if (n.type === 'orgLeader') {
      const d = n.data as LeaderNodeData
      if (d?.name) m.set(n.id, { label: d.name, kind: 'leader' })
    } else if (n.type === 'orgDept') {
      const d = n.data as DepartmentNodeData
      if (d?.phaseLabel) m.set(n.id, { label: d.phaseLabel, kind: 'dept' })
    }
  }
  return m
}, [initialNodes])

